CREATE TABLE customers (id BIGINT PRIMARY KEY); CREATE TABLE orders (id BIGINT PRIMARY KEY, customer_id BIGINT NOT NULL, CONSTRAINT fk_orders_customer FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT); CREATE TABLE order_items (id BIGINT PRIMARY KEY, order_id BIGINT NOT NULL, CONSTRAINT fk_items_order FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE);
